// Generated by Suite Builder from a crawl of the site. The pause between tests (-DtestDelay), and what the suite does
// when the site answers HTTP 429.
// EDIT RULES: do not edit this file; regenerating replaces all of it. Set the pause in pom.xml, testDelay.
// Creator: https://github.com/ghost-in-the-kernel
package com.frontlineinsurance.tests.core;

import java.util.function.IntSupplier;
import java.util.function.Supplier;
import java.util.function.ToIntFunction;

/**
 * The suite's pace, and its answer when the site says it is asked too often (HTTP 429). Built with --demo, for a site
 * the team does not own: 1000 ms before each test but the first and between the link report's requests, as the crawl
 * paced itself.
 * -DtestDelay (milliseconds), or the same in the pom's YOURS settings, sets the pause. The first test
 * does not wait. At a 429 the run stops: no further test or request is sent; the test that met it is not run to its end
 * (a skip, never a failure), the run's last lines and its report name it, the tests left are counted as not run, and
 * the run does not fail for the site's limit.
 */
public final class Pace {
    private static final long DELAY_MS = Long.parseLong(SiteConfig.value("testDelay", "1000"));
    /**
     * At a 429, the whole run stops (a suite built with --demo: BaseTest stops it); otherwise the request is asked
     * again after each of RETRY_WAITS_MS.
     */
    public static final boolean STOP_AT_TOO_MANY = true;
    private static final long[] RETRY_WAITS_MS = {};
    /** Too many requests: the site limits how often this run may ask. */
    public static final int TOO_MANY = 429;
    private static boolean first = true;
    /**
     * What this thread's test asked that still answered 429 after every wait: RerunOnce never tries that test again.
     */
    private static final ThreadLocal<String> STILL_TOO_MANY = new ThreadLocal<>();

    private Pace() {}

    /** Between two requests of one test (the link report's): waits testDelay. */
    public static void betweenRequests() {
        pause(DELAY_MS);
    }

    /** Before each test: waits testDelay, except before the first. */
    public static synchronized void betweenTests() {
        if (first) {
            first = false;
            return;
        }
        pause(DELAY_MS);
    }

    /**
     * A request's status, once the site's 429 is answered: any other status as it is. At a 429, a suite that stops
     * throws {@link TooMany}, and nothing more is asked; otherwise {@code again} asks once more after each wait, and
     * its last status is returned (a 429 still, an ordinary failure where the caller judges it).
     */
    public static int answered(int status, String what, IntSupplier again) {
        if (status != TOO_MANY) return status;
        if (STOP_AT_TOO_MANY) throw new TooMany(what
                + " answered HTTP 429 (too many requests): the site limited this run's requests");
        int now = status;
        for (long wait : RETRY_WAITS_MS) {
            if (now != TOO_MANY) return now;
            StepLog.note(what + " answered HTTP 429 (too many requests): asking again in " + wait / 1000 + " s");
            pause(wait);
            now = again.getAsInt();
        }
        if (now == TOO_MANY) STILL_TOO_MANY.set(what);
        return now;
    }

    /**
     * Every other request a test sends to the site (an address's answer, the not-found test, an API call): asked, and
     * a 429 answered as {@link #answered} says, the last answer returned.
     */
    public static <A> A asked(Supplier<A> ask, ToIntFunction<A> statusOf, String what) {
        @SuppressWarnings("unchecked")
        A[] last = (A[]) new Object[] {ask.get()};
        answered(statusOf.applyAsInt(last[0]), what, () -> statusOf.applyAsInt(last[0] = ask.get()));
        return last[0];
    }

    /**
     * What this thread's test asked that still answered 429 after every wait (a suite of the team's own site); null
     * when none.
     */
    public static String stillTooMany() {
        return STILL_TOO_MANY.get();
    }

    /** A test starts: no 429 met yet (RerunOnce). */
    public static void forget() {
        STILL_TOO_MANY.remove();
    }

    private static void pause(long ms) {
        if (ms <= 0) return;
        try {
            Thread.sleep(ms);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    /**
     * The site answered 429 in a suite that stops there: the run stops (BaseTest), and the test that met it is aborted,
     * not failed.
     */
    public static final class TooMany extends AssertionError {
        private static final long serialVersionUID = 1L;

        public TooMany(String message) {
            super(message);
        }
    }
}
